mapper.select:
SELECT t3.*, t2.role_name, t2.id role_id, account.username
FROM (

) account
JOIN t_role t2 ON account.role_id = t2.id
JOIN t_user_info t3 ON t3.user_id = account.id
WHERE account.id = #{userId}

SELECT COALESCE(t3.id, account.id) AS id, account.id AS user_id, COALESCE(NULLIF(t3.nickname, ''), account.username) AS nickname, t3.avatar, t3.ex1, t3.ex2, COALESCE(t3.deleted, 0) AS deleted, account.role_id, account.username FROM (
) account LEFT JOIN t_user_info t3 ON t3.user_id = account.id WHERE COALESCE(t3.deleted, 0) = 0
AND (account.username LIKE CONCAT('%', #{keyword}, '%') OR t3.nickname LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY COALESCE(t3.ex1, 0) DESC, account.id DESC LIMIT #{limit}
